def prepare_queen_outbox_proposal(message_id, sender_id, authority_queen_id, task_id, body, *, kind="REPORT", proposed_recipient_id=None, parent_message_sha256=None):
    # Deep-copy body
    deep_body = copy.deepcopy(body)

    # Build message keys
    message_keys = {
        "schema": SCHEMA,
        "message_id": message_id,
        "sender_id": sender_id,
        "recipient_id": authority_queen_id,
        "task_id": task_id,
        "kind": kind,
        "body": deep_body
    }

    # Add parent_message_sha256 only if given
    if parent_message_sha256 is not None:
        message_keys["parent_message_sha256"] = parent_message_sha256

    # Call validator once
    validation_result = validate_postal_message(message_keys)
    if validation_result[0] is None:
