    # Check peer casefold == "queen"
    peer = authority_queen_id.lower()
    if peer == "queen":
        return (None, ("proposed_recipient_is_queen",))

    # Return proposal schema hive_postal_outbox_proposal_v1
    proposal_schema = {
        "schema": "hive_postal_outbox_proposal_v1",
        "message": message_keys,
        "routing_request": None if proposed_recipient_id is None else {"recipient_id": proposed_recipient_id}
    }

    return (proposal_schema, ())

